3	namespace App\Models\Core\Gdpr;
4	
5	use App\Models\BaseModel;
6	use App\Models\Core\Professional\Professional;
7	use Illuminate\Database\Eloquent\Concerns\HasUuids;
8	use Illuminate\Database\Eloquent\Relations\BelongsTo;
9	
10	// V2: Audit row for Shopify GDPR webhooks. payload_hash unique index provides
11	// idempotency against Shopify retries — duplicate deliveries fail insert and
12	// the controller treats that as "already handled".
13	class GdprRequest extends BaseModel
14	{
15	    use HasUuids;
16	
17	    public const TOPIC_CUSTOMERS_DATA_REQUEST = 'customers/data_request';
18	
19	    public const TOPIC_CUSTOMERS_REDACT = 'customers/redact';
20	
21	    public const TOPIC_SHOP_REDACT = 'shop/redact';
22	
23	    public const STATUS_RECEIVED = 'received';
24	
25	    public const STATUS_PROCESSING = 'processing';
26	
27	    public const STATUS_COMPLETED = 'completed';
28	
29	    public const STATUS_FAILED = 'failed';
30	
31	    public const STATUS_SKIPPED = 'skipped';
32	
33	    protected $table = 'core.gdpr_requests';
34	
35	    public $incrementing = false;
36	
37	    protected $keyType = 'string';
38	
39	    protected $fillable = [
40	        'topic',
41	        'shop_domain',
42	        'shopify_shop_id',
43	        'payload_hash',
44	        'payload',
45	        'professional_id',
46	        'status',
47	        'error',
48	        'received_at',
49	        'completed_at',
50	    ];
51	
52	    protected $casts = [
53	        'payload' => 'array',
54	        'shopify_shop_id' => 'integer',
55	        'received_at' => 'datetime',
56	        'completed_at' => 'datetime',
57	    ];
58	
59	    public function professional(): BelongsTo
60	    {
61	        return $this->belongsTo(Professional::class, 'professional_id');
62	    }
63	
64	    public function markCompleted(): void
65	    {
66	        $this->update([
67	            'status' => self::STATUS_COMPLETED,
68	            'completed_at' => now(),
69	        ]);
70	    }
71	
72	    public function markSkipped(string $reason): void
73	    {
74	        $this->update([
75	            'status' => self::STATUS_SKIPPED,
76	            'error' => $reason,
77	            'completed_at' => now(),
78	        ]);
79	    }
80	
81	    public function markFailed(string $error): void
82	    {
83	        $this->update([
84	            'status' => self::STATUS_FAILED,
85	            'error' => mb_substr($error, 0, 2000),
86	        ]);
87	    }
88	}
