3	namespace App\Jobs\Shopify\Gdpr;
4	
5	use App\Mail\Gdpr\CustomerDataExportMail;
6	use App\Models\Core\Gdpr\GdprRequest;
7	use App\Models\Core\Professional\Customer;
8	use App\Models\Core\Professional\Professional;
9	use App\Services\Shopify\ShopifyShopResolver;
10	use Illuminate\Bus\Queueable;
11	use Illuminate\Contracts\Queue\ShouldQueue;
12	use Illuminate\Foundation\Bus\Dispatchable;
13	use Illuminate\Queue\InteractsWithQueue;
14	use Illuminate\Queue\SerializesModels;
15	use Illuminate\Support\Facades\DB;
16	use Illuminate\Support\Facades\Log;
17	use Illuminate\Support\Facades\Mail;
18	
19	// V2: Handles Shopify `customers/data_request`. Read-only — gathers every
20	// PII record we hold for the requesting customer (scoped to this shop's
21	// professional) and emails the JSON dump to the merchant. Merchant forwards
22	// to the customer; Shopify tracks compliance on their side.
23	class ExportCustomerDataJob implements ShouldQueue
24	{
25	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
26	
27	    public int $tries = 3;
28	
29	    public int $timeout = 120;
30	
31	    public function __construct(public string $gdprRequestId)
32	    {
33	        $this->onQueue(config('sidest.gdpr.queue'));
34	    }
35	
36	    public function backoff(): array
37	    {
38	        return [60, 300, 900];
39	    }
40	
41	    public function handle(): void
42	    {
43	        $resolver = app(ShopifyShopResolver::class);
44	        $gdpr = GdprRequest::find($this->gdprRequestId);
45	
46	        if (! $gdpr) {
47	            Log::warning('ExportCustomerDataJob: gdpr_requests row not found', ['id' => $this->gdprRequestId]);
48	
49	            return;
50	        }
51	
52	        if (in_array($gdpr->status, [GdprRequest::STATUS_COMPLETED, GdprRequest::STATUS_SKIPPED], true)) {
53	            return;
54	        }
55	
56	        $gdpr->update(['status' => GdprRequest::STATUS_PROCESSING]);
57	
58	        try {
59	            $professionalId = $resolver->resolveProfessionalId($gdpr->shop_domain);
60	
61	            if (! $professionalId) {
62	                $gdpr->markSkipped('no integration for shop_domain');
63	
64	                return;
65	            }
66	
67	            $gdpr->update(['professional_id' => $professionalId]);
68	
69	            $email = $gdpr->payload['customer']['email'] ?? null;
70	
71	            if (! is_string($email) || $email === '') {
72	                $gdpr->markSkipped('payload missing customer.email');
73	
74	                return;
75	            }
76	
77	            $professional = Professional::find($professionalId);
78	
79	            if (! $professional) {
80	                $gdpr->markSkipped('professional row gone');
81	
82	                return;
83	            }
84	
85	            // Professional model uses primary_email and public_contact_email
86	            $recipientEmail = $professional->public_contact_email ?: $professional->primary_email;
87	
88	            if (! $recipientEmail) {
89	                $gdpr->markFailed('professional has no contact email address');
90	
91	                return;
92	            }
93	
94	            $exportData = $this->gatherExportData($professionalId, $email);
95	
96	            Mail::to($recipientEmail)->send(
97	                new CustomerDataExportMail($gdpr->shop_domain, $email, $exportData)
98	            );
99	
100	            $gdpr->markCompleted();
101	
102	            Log::info('ExportCustomerDataJob completed.', [
103	                'gdpr_request_id' => $gdpr->id,
104	                'professional_id' => $professionalId,
105	                'recipient' => $recipientEmail,
106	                'customer_records' => count($exportData['customers'] ?? []),
107	            ]);
108	        } catch (\Throwable $e) {
109	            $gdpr->markFailed($e->getMessage());
110	            Log::error('ExportCustomerDataJob failed', [
111	                'gdpr_request_id' => $gdpr->id,
112	                'error' => $e->getMessage(),
113	            ]);
114	            throw $e;
115	        }
116	    }
117	
118	    /**
119	     * Gather every PII record we hold for the given customer email, scoped
120	     * to the specified professional. Groups by source table.
121	     *
122	     * @return array{customers: array, email_subscriptions: array, enquiries: array, lead_submissions: array, bookings: array}
123	     */
124	    private function gatherExportData(string $professionalId, string $email): array
125	    {
126	        $emailLc = mb_strtolower($email);
127	
128	        $customers = Customer::query()
129	            ->withTrashed()
130	            ->where('professional_id', $professionalId)
131	            ->whereRaw('LOWER(email) = ?', [$emailLc])
132	            ->get()
133	            ->map(fn (Customer $c) => [
134	                'id' => $c->id,
135	                'email' => $c->email,
136	                'phone' => $c->phone,
137	                'full_name' => $c->full_name,
138	                'source' => $c->source,
139	                'notes' => $c->notes,
140	                'created_at' => optional($c->created_at)->toIso8601String(),
141	                'updated_at' => optional($c->updated_at)->toIso8601String(),
142	            ])
143	            ->all();
144	
145	        $subscriptions = DB::connection('pgsql')
146	            ->table('notifications.email_subscriptions')
147	            ->where('professional_id', $professionalId)
148	            ->where('email_lc', $emailLc)
149	            ->get()
150	            ->map(fn ($r) => (array) $r)
151	            ->all();
152	
153	        // Deliberately exclude ip_hash and user_agent — technical fingerprint
154	        // metadata not provided by the customer; human-readable fields only.
155	        $enquiries = DB::connection('pgsql')
156	            ->table('site.enquiries')
157	            ->select(['id', 'name', 'email', 'phone', 'subject', 'message', 'created_at'])
158	            ->where('professional_id', $professionalId)
159	            ->whereRaw('LOWER(email) = ?', [$emailLc])
160	            ->get()
161	            ->map(fn ($r) => (array) $r)
162	            ->all();
163	
164	        $customerIds = array_column($customers, 'id');
165	
166	        $leadSubmissions = [];
167	        if (! empty($customerIds)) {
