3	namespace App\Jobs\Shopify\Gdpr;
4	
5	use App\Models\Core\Gdpr\GdprRequest;
6	use App\Models\Core\Professional\Customer;
7	use App\Services\Shopify\ShopifyShopResolver;
8	use Illuminate\Bus\Queueable;
9	use Illuminate\Contracts\Queue\ShouldQueue;
10	use Illuminate\Foundation\Bus\Dispatchable;
11	use Illuminate\Queue\InteractsWithQueue;
12	use Illuminate\Queue\SerializesModels;
13	use Illuminate\Support\Facades\DB;
14	use Illuminate\Support\Facades\Log;
15	use Illuminate\Support\Str;
16	
17	// V2: Handles Shopify `customers/redact` webhook. Anonymises the matching
18	// core.customers row (kept for commission ledger integrity) and hard-deletes
19	// email_subscriptions + site.enquiries rows for the customer email.
20	// Also scrubs denormalised PII from analytics.booking_events — those rows
21	// have no customer_id FK so they don't cascade via the customers anonymisation.
22	class RedactCustomerJob implements ShouldQueue
23	{
24	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
25	
26	    public int $tries = 3;
27	
28	    public int $timeout = 120;
29	
30	    public function __construct(public string $gdprRequestId)
31	    {
32	        $this->onQueue(config('sidest.gdpr.queue'));
33	    }
34	
35	    public function backoff(): array
36	    {
37	        return [30, 120, 600];
38	    }
39	
40	    public function handle(): void
41	    {
42	        $resolver = app(ShopifyShopResolver::class);
43	        $gdpr = GdprRequest::find($this->gdprRequestId);
44	
45	        if (! $gdpr) {
46	            Log::warning('RedactCustomerJob: gdpr_requests row not found', ['id' => $this->gdprRequestId]);
47	
48	            return;
49	        }
50	
51	        if (in_array($gdpr->status, [GdprRequest::STATUS_COMPLETED, GdprRequest::STATUS_SKIPPED], true)) {
52	            return;
53	        }
54	
55	        $gdpr->update(['status' => GdprRequest::STATUS_PROCESSING]);
56	
57	        try {
58	            $professionalId = $resolver->resolveProfessionalId($gdpr->shop_domain);
59	
60	            if (! $professionalId) {
61	                $gdpr->markSkipped('no integration for shop_domain');
62	
63	                return;
64	            }
65	
66	            $gdpr->update(['professional_id' => $professionalId]);
67	
68	            $email = $this->customerEmail($gdpr->payload);
69	
70	            if ($email === null) {
71	                $gdpr->markSkipped('payload missing customer.email');
72	
73	                return;
74	            }
75	
76	            // Include soft-deleted rows — they still hold real PII and must
77	            // be anonymised on a GDPR redact request.
78	            $customer = Customer::query()
79	                ->withTrashed()
80	                ->where('professional_id', $professionalId)
81	                ->whereRaw('LOWER(email) = ?', [mb_strtolower($email)])
82	                ->whereNull('redacted_at')
83	                ->first();
84	
85	            if ($customer) {
86	                $placeholderDomain = config('sidest.gdpr.redact_placeholder_domain', 'gdpr.sidest.io');
87	
88	                $customer->update([
89	                    'email' => 'redacted-'.Str::uuid()->toString().'@'.$placeholderDomain,
90	                    'phone' => null,
91	                    'full_name' => 'Redacted Customer',
92	                    'external_id' => null,
93	                    'notes' => null,
94	                    'marketing_opt_in_cached' => null,
95	                    'redacted_at' => now(),
96	                ]);
97	            }
98	
99	            $emailLc = mb_strtolower($email);
100	
101	            // Run sibling cleanup unconditionally on the email address.
102	            // A visitor who only submitted a contact enquiry (no booking) will
103	            // have no core.customers row but still have real PII in these tables.
104	            $deletedSubs = DB::connection('pgsql')
105	                ->table('notifications.email_subscriptions')
106	                ->where('professional_id', $professionalId)
107	                ->where('email_lc', $emailLc)
108	                ->delete();
109	
110	            $deletedEnquiries = DB::connection('pgsql')
111	                ->table('site.enquiries')
112	                ->where('professional_id', $professionalId)
113	                ->whereRaw('LOWER(email) = ?', [$emailLc])
114	                ->delete();
115	
116	            // Scrub denormalised PII on booking_events. These rows have no
117	            // customer_id FK so core.customers anonymisation doesn't cascade.
118	            // raw_payload (full Square/Fresha booking JSON) is reset to '{}' because
119	            // it contains the customer object. '{}'::jsonb on Postgres; plain '{}' on SQLite.
120	            $scrubbedBookings = DB::connection('pgsql')
121	                ->table('analytics.booking_events')
122	                ->where('professional_id', $professionalId)
123	                ->whereRaw('LOWER(customer_email) = ?', [$emailLc])
124	                ->update([
125	                    'customer_name' => null,
126	                    'customer_email' => null,
127	                    'customer_phone' => null,
128	                    'raw_payload' => '{}',
129	                    'updated_at' => now(),
130	                ]);
131	
132	            // Nothing found for this email — legitimate skip (email address may
133	            // never have interacted with this shop via Side St).
134	            if (! $customer && $deletedSubs === 0 && $deletedEnquiries === 0 && $scrubbedBookings === 0) {
135	                $gdpr->markSkipped('no data found for email in this shop');
136	
137	                return;
138	            }
139	
140	            $gdpr->markCompleted();
141	
142	            Log::info('RedactCustomerJob completed.', [
143	                'gdpr_request_id' => $gdpr->id,
144	                'professional_id' => $professionalId,
145	                'customer_id' => $customer?->id,
146	                'deleted_subscriptions' => $deletedSubs,
147	                'deleted_enquiries' => $deletedEnquiries,
148	                'scrubbed_bookings' => $scrubbedBookings,
149	            ]);
150	        } catch (\Throwable $e) {
151	            $gdpr->markFailed($e->getMessage());
152	            Log::error('RedactCustomerJob failed', [
153	                'gdpr_request_id' => $gdpr->id,
154	                'error' => $e->getMessage(),
155	            ]);
156	            throw $e;
157	        }
158	    }
159	
160	    /**
161	     * Pluck the customer email out of a customers/redact payload.
162	     * Shopify shape: { "customer": { "id", "email", "phone" }, "orders_to_redact": [...] }
163	     */
164	    private function customerEmail(array $payload): ?string
165	    {
166	        $email = $payload['customer']['email'] ?? null;
167	
168	        return is_string($email) && $email !== '' ? $email : null;
169	    }
170	}
