3	namespace App\Jobs\Shopify\Gdpr;
4	
5	use App\Models\Commerce\AffiliateProductSelection;
6	use App\Models\Core\Gdpr\GdprRequest;
7	use App\Models\Core\Professional\Customer;
8	use App\Services\Shopify\ShopifyShopResolver;
9	use Illuminate\Bus\Queueable;
10	use Illuminate\Contracts\Queue\ShouldQueue;
11	use Illuminate\Foundation\Bus\Dispatchable;
12	use Illuminate\Queue\InteractsWithQueue;
13	use Illuminate\Queue\SerializesModels;
14	use Illuminate\Support\Facades\Log;
15	use Illuminate\Support\Str;
16	
17	// V2: Handles Shopify `shop/redact` webhook. NARROW scope — removes the Shopify
18	// integration and Shopify-derived data, but leaves the professional account
19	// intact (they may still be using Fresha or Square). Timeout is generous because
20	// a mature shop can have thousands of Shopify-sourced customers to anonymise.
21	class RedactShopJob implements ShouldQueue
22	{
23	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
24	
25	    public int $tries = 3;
26	
27	    public int $timeout = 600;
28	
29	    public function __construct(public string $gdprRequestId)
30	    {
31	        // redis_gdpr connection has retry_after=660 so Redis won't re-queue
32	        // this job while the 600s chunkById sweep is still running.
33	        $this->onConnection('redis_gdpr')->onQueue(config('sidest.gdpr.queue'));
34	    }
35	
36	    public function backoff(): array
37	    {
38	        return [60, 300, 900];
39	    }
40	
41	    public function handle(): void
42	    {
43	        $resolver = app(ShopifyShopResolver::class);
44	        $gdpr = GdprRequest::find($this->gdprRequestId);
45	
46	        if (! $gdpr) {
47	            Log::warning('RedactShopJob: gdpr_requests row not found', ['id' => $this->gdprRequestId]);
48	
49	            return;
50	        }
51	
52	        // Idempotent: re-run on a completed/skipped request is a no-op. Shopify
53	        // retries fire at the transport layer; the payload_hash unique index
54	        // prevents duplicate rows, but if this job itself is re-queued (Horizon
55	        // restart, etc.) we must not re-process.
56	        if (in_array($gdpr->status, [GdprRequest::STATUS_COMPLETED, GdprRequest::STATUS_SKIPPED], true)) {
57	            return;
58	        }
59	
60	        $gdpr->update(['status' => GdprRequest::STATUS_PROCESSING]);
61	
62	        try {
63	            $integration = $resolver->resolveIntegration($gdpr->shop_domain);
64	
65	            if (! $integration) {
66	                $gdpr->markSkipped('no integration for shop_domain (already redacted or never installed)');
67	
68	                return;
69	            }
70	
71	            $professionalId = $integration->professional_id;
72	            $gdpr->update(['professional_id' => $professionalId]);
73	
74	            // 1. Revoke API access FIRST. If anything below crashes, the
75	            //    integration is already cut off from Shopify.
76	            $integration->update([
77	                'access_token' => null,
78	                'refresh_token' => null,
79	            ]);
80	
81	            // 2. Delete affiliate product selections scoped to this brand.
82	            //    Shopify product GIDs become stale the moment the integration is gone.
83	            $deletedSelections = AffiliateProductSelection::query()
84	                ->where('brand_professional_id', $professionalId)
85	                ->delete();
86	
87	            // 3. Anonymise Shopify-sourced customers. Other sources (fresha,
88	            //    square, manual) are preserved — the professional may still be
89	            //    using those integrations.
90	            $anonymisedCount = $this->anonymiseShopifyCustomers($professionalId);
91	
92	            // 4. Delete the integration row LAST. This removes the
93	            //    shopify_shop_domain key, so subsequent retries fall into the
94	            //    "no integration" skip branch above.
95	            $integration->delete();
96	
97	            $gdpr->markCompleted();
98	
99	            Log::info('RedactShopJob completed (narrow scope).', [
100	                'gdpr_request_id' => $gdpr->id,
101	                'professional_id' => $professionalId,
102	                'shop_domain' => $gdpr->shop_domain,
103	                'deleted_selections' => $deletedSelections,
104	                'anonymised_customers' => $anonymisedCount,
105	            ]);
106	        } catch (\Throwable $e) {
107	            $gdpr->markFailed($e->getMessage());
108	            Log::error('RedactShopJob failed', [
109	                'gdpr_request_id' => $gdpr->id,
110	                'error' => $e->getMessage(),
111	            ]);
112	            throw $e;
113	        }
114	    }
115	
116	    /**
117	     * Anonymise every customer row tied to this professional and sourced from
118	     * Shopify. Email becomes redacted-{uuid}@placeholder, name becomes a
119	     * literal placeholder, phone and external_id are nulled.
120	     *
121	     * Uses chunkById(500) to keep memory bounded at scale — a mature shop
122	     * can have tens of thousands of customers. chunkById is safe here: we
123	     * update `redacted_at` on each row, so already-processed rows drop out
124	     * of the `whereNull('redacted_at')` filter, and the id cursor only
125	     * advances forward.
126	     */
127	    private function anonymiseShopifyCustomers(string $professionalId): int
128	    {
129	        $placeholderDomain = config('sidest.gdpr.redact_placeholder_domain', 'gdpr.sidest.io');
130	        $count = 0;
131	
132	        Customer::query()
133	            ->withTrashed()
134	            ->where('professional_id', $professionalId)
135	            ->where('source', 'shopify')
136	            ->whereNull('redacted_at')
137	            ->chunkById(500, function ($customers) use ($placeholderDomain, &$count) {
138	                foreach ($customers as $customer) {
139	                    $customer->update([
140	                        'email' => 'redacted-'.Str::uuid()->toString().'@'.$placeholderDomain,
141	                        'phone' => null,
142	                        'full_name' => 'Redacted Customer',
143	                        'external_id' => null,
144	                        'notes' => null,
145	                        'marketing_opt_in_cached' => null,
146	                        'redacted_at' => now(),
147	                    ]);
148	                    $count++;
149	                }
150	            });
151	
152	        return $count;
153	    }
154	}
